import fs from 'fs/promises';
import path from 'path';
import { createHash, randomUUID } from 'crypto';
import { z } from 'zod';
import {
  ProfilePacketSchema,
  PROFILE_CANDIDATE_IMAGE_LIMIT,
} from '../../types/design-profile';
import type { ProfileRecords } from '../../storage/profiles/ProfileRecords';
import type {
  ProfilePacket,
  ProfilePreparation as Input,
  ProfileCandidate,
  ProfileObservation,
} from '../../types/design-profile';
import type { ProfileIndex } from './ProfileIndex';
import type { ProfileAgent } from './ProfileAgent';
import type { ProfileMedia } from './ProfileMedia';
import { selectionSchema, selectProfileReferences } from './profileSelection';
import { reportedProfileUsage } from './modelContract';
import { selectionContext } from './selectionContext';
import { profileSearchQueries } from './profileQueries';
import { errnoCode } from '../../utils/errnoCode';
import { ProfileContextConflict } from '../../storage/profiles/contextReceipts';
import { resolveReferenceKeys } from './referenceKeys';

type DeliveredReference = Omit<ProfileCandidate, 'observation'> & {
  observation: ProfileObservation | null;
  reason: string;
};

interface PreparationOptions {
  signal?: AbortSignal;
  saveUploads?: (
    signal: AbortSignal,
  ) => Promise<Pick<ProfilePacket, 'suppliedReferences' | 'failedUploadCount'>>;
}

const PREPARATION_TIMEOUT_MS = 30_000;
const CURSOR_PREPARATION_TIMEOUT_MS = 50_000;
const MAX_CANDIDATES = 12;
const MAX_SELECTED_IMAGES = 3;

const mergeRankedCandidates = (
  rankedByQuery: ProfileCandidate[][],
): Map<string, ProfileCandidate> => {
  const merged = new Map<string, ProfileCandidate>();
  const share = Math.ceil(MAX_CANDIDATES / Math.max(rankedByQuery.length, 1));
  const longest = Math.max(0, ...rankedByQuery.map((ranked) => ranked.length));
  const fill = (isShared: boolean) => {
    const taken = rankedByQuery.map(() => 0);
    for (let rank = 0; rank < longest; rank += 1)
      for (const [query, ranked] of rankedByQuery.entries()) {
        const candidate = ranked[rank];
        if (
          !candidate ||
          merged.has(candidate.reference.id) ||
          merged.size >= MAX_CANDIDATES ||
          (isShared && taken[query] >= share)
        )
          continue;
        taken[query] += 1;
        merged.set(candidate.reference.id, candidate);
      }
  };
  fill(true);
  fill(false);
  return merged;
};

export class ProfilePreparation {
  private readonly inFlight = new Map<
    string,
    { input: string; run: Promise<ProfilePacket> }
  >();
  constructor(
    private readonly records: ProfileRecords,
    private readonly index: ProfileIndex,
    private readonly agent: ProfileAgent,
    private readonly media: ProfileMedia,
  ) {}

  prepare(
    input: Input,
    options: PreparationOptions = {},
  ): Promise<ProfilePacket> {
    const key = createHash('sha256').update(input.requestId).digest('hex');
    const existing = this.inFlight.get(key);
    if (existing) {
      if (existing.input !== JSON.stringify(input))
        return Promise.reject(
          new Error('Profile request ID is already bound to different inputs'),
        );
      return existing.run;
    }
    const run = this.loadOrPrepare(input, key, options).finally(() =>
      this.inFlight.delete(key),
    );
    this.inFlight.set(key, { input: JSON.stringify(input), run });
    return run;
  }

  private async loadOrPrepare(
    input: Input,
    key: string,
    options: PreparationOptions,
  ): Promise<ProfilePacket> {
    const directory = path.join(this.records.directory, 'requests', key);
    const filename = path.join(directory, 'packet.json');
    const fingerprint = createHash('sha256')
      .update(JSON.stringify(input))
      .digest('hex');
    try {
      const saved = z
        .object({ fingerprint: z.string(), packet: ProfilePacketSchema })
        .parse(JSON.parse(await fs.readFile(filename, 'utf8')));
      if (saved.fingerprint !== fingerprint)
        throw new Error(
          'Profile request ID is already bound to different inputs',
        );
      return saved.packet;
    } catch (error) {
      if (errnoCode(error) !== 'ENOENT') throw error;
    }
    await fs.mkdir(directory, { recursive: true, mode: 0o700 });
    const started = Date.now();
    const packet: ProfilePacket = {
      requestId: input.requestId,
      status: 'empty',
      queries: [],
      candidateIds: [],
      selected: [],
      contextText: '',
      images: [],
      durationMs: 0,
    };
    const signal = AbortSignal.any([
      AbortSignal.timeout(
        input.runtime === 'cursor'
          ? CURSOR_PREPARATION_TIMEOUT_MS
          : PREPARATION_TIMEOUT_MS,
      ),
      ...(options.signal ? [options.signal] : []),
    ]);
    if (input.mode === 'off' || !this.records.profile().isEnabled)
      packet.status = 'off';
    else {
      options.signal?.throwIfAborted();
      if (options.saveUploads)
        Object.assign(packet, await options.saveUploads(signal));
      options.signal?.throwIfAborted();
      if (input.mode === 'uploads' && !options.saveUploads)
        packet.status = 'off';
      if (input.mode === 'auto') {
        try {
          if (input.referencePicks)
            await this.selectPicks(input, packet, directory, signal);
          else await this.select(input, packet, directory, signal);
        } catch (error) {
          if (error instanceof ProfileContextConflict) throw error;
          packet.status = signal.aborted ? 'timeout' : 'unavailable';
          packet.selected = [];
          packet.images = [];
          packet.contextText = '';
        }
      }
    }
    packet.durationMs = Date.now() - started;
    const staging = `${filename}.${randomUUID()}.partial`;
    await fs.writeFile(staging, JSON.stringify({ fingerprint, packet }), {
      mode: 0o600,
    });
    await fs.rename(staging, filename);
    return packet;
  }

  private async select(
    input: Input,
    packet: ProfilePacket,
    directory: string,
    signal: AbortSignal,
  ): Promise<void> {
    if (
      !this.records.candidates(
        this.records
          .references()
          .map(({ id, revision }) => ({ referenceId: id, revision })),
      ).length
    )
      return;
    await this.index.flush(input.runtime, signal);
    const rankedByQuery: ProfileCandidate[][] = [];
    for (const query of profileSearchQueries(input.instruction)) {
      signal.throwIfAborted();
      packet.queries.push(query);
      rankedByQuery.push(
        (
          await this.index.search({
            runtime: input.runtime,
            query,
            signal,
          })
        ).flatMap((candidate) => {
          const sources = candidate.sources.filter(
            (source) => !input.excludedSourceIds.includes(source.id),
          );
          return sources.length &&
            !input.excludedReferenceIds.includes(candidate.reference.id)
            ? [{ ...candidate, sources }]
            : [];
        }),
      );
    }
    const candidates = mergeRankedCandidates(rankedByQuery);
    const images: string[] = [];
    const supplied: ProfileCandidate[] = [];
    const referenceImages = new Map<string, string[]>();
    const descriptions: unknown[] = [];
    for (const candidate of candidates.values()) {
      const paths = await Promise.all(
        candidate.reference.media.map((media) => this.media.resolve(media)),
      );
      if (images.length + paths.length > PROFILE_CANDIDATE_IMAGE_LIMIT)
        continue;
      const imageIndexes = paths.map((_image, index) => images.length + index);
      images.push(...paths);
      supplied.push(candidate);
      referenceImages.set(candidate.reference.id, paths);
      descriptions.push({
        id: candidate.reference.id,
        title: candidate.reference.title,
        description: candidate.observation.description.slice(0, 1000),
        evidence: candidate.observation.evidence,
        note: candidate.reference.note,
        variant: candidate.reference.variant,
        imageIndexes,
      });
    }
    packet.candidateIds = supplied.map((candidate) => candidate.reference.id);
    if (!supplied.length) return;
    const result = await this.agent.run({
      runtime: input.runtime,
      signal,
      images,
      schema: selectionSchema,
      prompt: `Choose only references that materially help this design request. Empty selection is correct for weak, unrelated, or non-design requests. Inspect the actual images; describe why each selection helps. Do not treat a saved image as a confirmed user preference. Request: ${input.instruction}\nCandidate reference data: ${JSON.stringify(descriptions)}`,
    });
    packet.usage = reportedProfileUsage(result.usage);
    const selected = selectProfileReferences(result.value, supplied);
    const inspected = new Set(result.inspectedImages);
    if (
      selected.some((candidate) =>
        referenceImages
          .get(candidate.reference.id)
          ?.some((image) => !inspected.has(image)),
      )
    )
      throw new Error(
        'The selected agent did not inspect the selected reference images',
      );
    await this.deliver({
      input,
      packet,
      directory,
      signal,
      selected,
      isCurrent: (candidate) =>
        this.records.candidates([
          {
            referenceId: candidate.reference.id,
            revision: candidate.reference.revision,
          },
        ]).length > 0,
    });
  }

  private async selectPicks(
    input: Input,
    packet: ProfilePacket,
    directory: string,
    signal: AbortSignal,
  ): Promise<void> {
    const picks = input.referencePicks;
    if (!picks) return;
    if (picks.profileId !== this.records.profile().id)
      throw new ProfileContextConflict(
        'Reference picks belong to a different design library. Copy the selection again from Design library.',
      );
    const resolved = resolveReferenceKeys(
      this.records,
      picks.picks.map((pick) => pick.key),
    );
    if (!resolved)
      throw new ProfileContextConflict(
        'A picked saved reference is unavailable. Copy the selection again from Design library.',
      );
    const reasons = new Map(picks.picks.map((pick) => [pick.key, pick.reason]));
    const sources = this.records.sources();
    const selected = resolved.flatMap(({ key, reference: picked }) => {
      const reference = this.records.reference(picked.id);
      if (!reference || input.excludedReferenceIds.includes(reference.id))
        return [];
      return [
        {
          reference,
          observation: this.records.observation(reference.id),
          sources: sources
            .filter((source) => picked.sourceIds.includes(source.id))
            .map(({ id, provider, remoteId, title, url }) => ({
              id,
              provider,
              remoteId,
              title,
              ...(url ? { url } : {}),
            })),
          reason: reasons.get(key) ?? '',
        },
      ];
    });
    packet.candidateIds = selected.map((candidate) => candidate.reference.id);
    await this.deliver({
      input,
      packet,
      directory,
      signal,
      selected,
      selectedBy: 'host',
      isCurrent: (candidate) =>
        this.records.reference(candidate.reference.id)?.revision ===
        candidate.reference.revision,
    });
  }

  private async deliver({
    input,
    packet,
    directory,
    signal,
    selected,
    selectedBy,
    isCurrent,
  }: {
    input: Input;
    packet: ProfilePacket;
    directory: string;
    signal: AbortSignal;
    selected: DeliveredReference[];
    selectedBy?: 'host';
    isCurrent: (candidate: DeliveredReference) => boolean;
  }): Promise<void> {
    const seen = new Set<string>();
    const explicit = new Set(input.excludedMediaHashes);
    const retained: DeliveredReference[] = [];
    let imageCount = 0;
    for (const candidate of selected) {
      signal.throwIfAborted();
      if (!isCurrent(candidate)) continue;
      const available = candidate.reference.media.filter(
        (image) => !seen.has(image.hash),
      );
      const additional = available.filter((image) => !explicit.has(image.hash));
      if (imageCount + additional.length > MAX_SELECTED_IMAGES) continue;
      for (const media of available) {
        const original = await this.media.resolve(media);
        const destination = path.join(directory, path.basename(original));
        await fs.copyFile(original, destination);
        packet.images.push({
          path: destination,
          hash: media.hash,
          mimeType: media.mimeType,
        });
        seen.add(media.hash);
      }
      imageCount += additional.length;
      retained.push(candidate);
      packet.selected.push({
        id: candidate.reference.id,
        revision: candidate.reference.revision,
        title: candidate.reference.title.trim() || 'Untitled reference',
        ...(candidate.reference.url ? { url: candidate.reference.url } : {}),
        mediaHashes: candidate.reference.media.map((media) => media.hash),
        reason: candidate.reason,
        sourceTitles: candidate.sources.map((source) => source.title),
        ...(candidate.reference.variant
          ? { variant: candidate.reference.variant }
          : {}),
        ...(selectedBy ? { selectedBy } : {}),
      });
    }
    packet.contextText = selectionContext(retained);
    if (packet.selected.length) packet.status = 'selected';
  }
}
